eg_near_lower":0,"leg_near_upper":5,"neck":0,"torso":0},"facing":"left","height":0.54,"role":"lead","x":0.76}],"mark":true,"props":[{"dx":0,"dy":0,"figure":-1,"inner":"none","joint":"hip","kind":"clock","show":true,"size":0.2,"x":0.18,"y":0.42},{"dx":0,"dy":0,"figure":-1,"inner":"none","joint":"hip","kind":"toolbox","show":true,"size":0.14,"x":0.38,"y":0.82},{"dx":0.05,"dy":-0.4,"figure":0,"inner":"clock","joint":"head","kind":"think_question","show":false,"size":0.26,"x":0,"y":0},{"dx":0.05,"dy":-0.4,"figure":1,"inner":"clock","joint":"head","kind":"bubble_check","show":false,"size":0.26,"x":0,"y":0},{"dx":0,"dy":0,"figure":-1,"inner":"none","joint":"hip","kind":"check_mark","show":true,"size":0.12,"x":0.52,"y":0.14}],"t":9}]},"kind":"keyframes"},"parts":[{"id":"p1","reason":"残業をする本人として新人を描いた","statement":"s1","target":{"index":0,"type":"figure"}},{"id":"p2","reason":"残業代を払う会社側を上の人で表した","statement":"s1","target":{"index":1,"type":"figure"}},{"id":"p3","reason":"17時から20時の時間帯を壁の時計で示した","statement":"s1","target":{"index":0,"type":"prop"}},{"id":"p4","reason":"時間外も作業している場面を道具箱で示した","statement":"s1","target":{"index":1,"type":"prop"}},{"id":"p5","reason":"残業の時間の扱いに迷う様子を見せた","statement":"s1","target":{"index":2,"type":"prop"}},{"id":"p6","reason":"会社がその時間の残業代を払うと伝える様子","statement":"s1","target":{"index":3,"type":"prop"}},{"id":"p7","reason":"割増賃金が払われると確かめた印","statement":"s1","target":{"index":4,"type":"prop"}}],"rule":"会社は、17 時から 20 時までの残業に残業代（割増賃金）を払う。","version":1,"why":"17時から20時までの残業には割増賃金が払われると知らないと、働いた分の賃金を正しく受け取れないおそれがあるため。"}', '2026-11-02T16:53:25.831Z', '0e9ba7738608cf3ead8e34b1c4829d35efae35a916dc51647ddb1680db268efb', 'bd24f9172d64cfe7592c8c1ce8725b06183856cf929fc058a4784bbbe309b295');
