:-0.1,"dy":-0.4,"figure":1,"inner":"clock","joint":"head","kind":"bubble_check","show":true,"size":0.26,"x":0,"y":0},{"dx":0,"dy":0,"figure":-1,"inner":"none","joint":"hip","kind":"circle_mark","show":false,"size":0.16,"x":0.85,"y":0.15}],"t":9}]},"kind":"keyframes"},"parts":[{"id":"p1","reason":"休憩を取る人として、作業→休む→作業に戻る流れを見せる","statement":"s1","target":{"index":0,"type":"figure"}},{"id":"p2","reason":"会社が休憩時間を決めることを、上の人が時計を指して示す","statement":"s1","target":{"index":1,"type":"figure"}},{"id":"p3","reason":"12時から13時という決まった時間を時計で表す","statement":"s1","target":{"index":0,"type":"prop"}},{"id":"p4","reason":"休憩の前後は作業中であることを示す","statement":"s1","target":{"index":1,"type":"prop"}},{"id":"p5","reason":"上の人が時刻を確かめて休憩の始まりと終わりを伝える","statement":"s1","target":{"index":2,"type":"prop"}},{"id":"p6","reason":"決まった時間に休むのが正しいことを示す","statement":"s1","target":{"index":3,"type":"prop"}}],"rule":"会社は、休憩を 12 時から 13 時までの 1 時間とする。","version":1,"why":"決まった時間にきちんと休まないと、疲れがたまって作業中の事故やけがにつながるからです。"}', '2026-11-02T16:54:21.228Z', '9c46700215a75e5e197240c72ec31e363b035b81b266db7434312b9200a338f2', '4089f82669095220455158da18e7dcf9be3877a6aedfafc0ed550ed406e8b9d9');
