:{"index":0,"type":"prop"}},{"id":"p4","reason":"壁の時計で勤務時間・出勤を表す","statement":"s1","target":{"index":1,"type":"prop"}},{"id":"p5","reason":"時間なのに来ないと上の人が迷う様子","statement":"s1","target":{"index":2,"type":"prop"}},{"id":"p6","reason":"無断で職場を離れ欠勤することの禁止","statement":"s1","target":{"index":3,"type":"prop"}},{"id":"p7","reason":"上の人が出口を指し×で解雇されることを示す","statement":"s2","target":{"index":4,"type":"prop"}},{"id":"p8","reason":"出勤を出勤簿で確かめたことを吹き出しで見せる","statement":"s1","target":{"index":5,"type":"prop"}},{"id":"p9","reason":"きちんと出勤・報告するのが正しい行動である印","statement":"s1","target":{"index":6,"type":"prop"}}],"rule":"無断欠勤を続けるなど、就業規則の解雇の事由に当たることをしない。","version":1,"why":"解雇されることがある。"}', '2026-11-02T16:59:14.507Z', '06eaf5d57d9bea0c323f902232ec114ad3ea86b1a45325f624525fdffc218fa6', '5fbf9b318bb2700fb09acc5bb10181b38c69531130105e74df64cdaf5d9413a7');
