dex":0,"type":"figure"}},{"id":"p2","reason":"知らせを受ける親方","statement":"s1","target":{"index":1,"type":"figure"}},{"id":"p3","reason":"異常のある場所として壁の盤","statement":"s1","target":{"index":0,"type":"prop"}},{"id":"p4","reason":"盤の異常に気づいたことを考える吹き出しで示す","statement":"s1","target":{"index":1,"type":"prop"}},{"id":"p5","reason":"盤の異常を親方に話して知らせる","statement":"s1","target":{"index":2,"type":"prop"}},{"id":"p6","reason":"親方が受けて確かめ、事故を防げたことを示す","statement":"s2","target":{"index":3,"type":"prop"}},{"id":"p7","reason":"すぐ知らせるのが正しいやり方の印","statement":"s1","target":{"index":4,"type":"prop"}}],"rule":"異常に気づいたら、すぐに親方に知らせる。","version":1,"why":"早く知らせれば、事故を防げるため。"}', '2026-11-02T17:00:27.465Z', '701b2672a7003f3d121f7492775902f3718a25dc0c5e1aaa490b869e79ed7fe9', 'faceac8a0f6e82347313682af7a660e5ba0ae461a19a2ce1d4fbacc519e2c6c8');
