INSERT OR IGNORE INTO extractions (tenant_id, id, input, rules, created_at) VALUES ('demo', '053ffe18-c78a-41dd-a5a6-79d921b46092', '{"text":"労働条件通知書（公開デモ用。架空の会社の値。厚生労働省のモデル労働条件通知書の項目にならって書いた）\n事業場: ほしぞら電設株式会社（架空の会社）\n【始業・終業の時刻】\n始業は 9 時、終業は 17 時とする。\n【休憩時間】\n休憩は 12 時から 13 時までの 1 時間とする。\n【所定時間外労働】\n17 時から 20 時までの残業には、残業代（割増賃金）を払う。\n【休日】\n休日は毎週土曜日と日曜日の 2 日とする。\n【その他（職場の決まり）】\n毎朝 9 時に朝礼を行うので、9 時までに集まる。\n遅れるときや休むときは、始業の前に電話で知らせる。仕事の段取りを組み直すためである。\n作業の前とトイレの後には、手を洗う。食中毒や病気がうつるのを防ぐためである。\n【解雇の事由】\n無断欠勤を続けるなど、就業規則の解雇の事由に当たることをすると、解雇されることがある。\n【安全の決まり】\n異常に気づいたら、すぐに親方に知らせる。早く知らせれば、事故を防げるためである。\n異常に気づいてから 10 分たって知らせるのでは遅い。","focus":null,"source":{"kind":"doc","doc":"demo-notice","pages":[{"page":1,"lines":19}]}}', '[{"kind":"do","text":"会社は、始業を 9 時、終業を 17 時とする。","from":{"quote":"始業は 9 時、終業は 17 時とする。","line":4,"line_end":4,"found":true},"reasons":[],"checklist":false,"reworded":false,"where":{"page":1,"line":4}},{"kind":"do","text":"会社は、休憩を 12 時から 13 時までの 1 時間とする。","from":{"quote":"休憩は 12 時から 13 時までの 1 時間とする。","line":6,"line_end":6,"found":true},"reasons":[],"checklist":false,"reworded":false,"where":{"page":1,"line":6}},{"kind":"do","text":"会社は、17 時から 20 時までの残業に残業代（割増賃金）を払う。","from":{"quote":"17 時から 20 時までの残業には、残業代（割増賃金）を払う。","line":8,"line_end":8,"found":true},"reasons":[],"checklist":false,"reworded":false,"where":{"page":1,"line":8}},{"kind":"do","text":"会社は、休日を毎週土曜日と日曜日の 2 日とする。","from":{"quote":"休日は毎週土曜日と日曜日の 2 日とする。","line":10,"line_end":10,"found":true},"reasons":[],"checklist":false,"reworded":false,"where":{"page":1,"line":10}},{"kind":"do","text":"毎朝 9 時までに集まる。","from":{"quote":"毎朝 9 時に朝礼を行うので、9 時までに集まる。","line":12,"line_end":12,"found":true},"reasons":[{"text":"毎朝 9 時に朝礼を行うため。","from":{"quote":"毎朝 9 時に朝礼を行うので","line":12,"line_end":12,"found":true},"stated":true,"where":{"page":1,"line":12}}],"checklist":false,"reworded":false,"where":{"page":1,"line":12}},{"kind":"do","text":"遅れるときや休むときは、始業の前に電話で知らせる。","from":{"quote":"遅れるときや休むときは、始業の前に電話で知らせる。","line":13,"line_end":13,"found":true},"reasons":[{"text":"仕事の段取りを組み直すため。","from":{"quote":"仕事の段取りを組み直すためである。","line":13,"line_end":13,"found":true},"stated":true,"where":{"page":1,"line":13}}],"checklist":false,"reworded":false,"where":{"page":1,"line":13}},{"kind":"do","text":"作業の前とトイレの後には、手を洗う。","from":{"quote":"作業の前とトイレの後には、手を洗う。","line":14,"line_end":14,"found":true},"reasons":[{"text":"食中毒や病気がうつるのを防ぐため。","from":{"quote":"食中毒や病気がうつるのを防ぐためである。","line":14,"line_end":14,"found":true},"stated":true,"where":{"page":1,"line":14}}],"checklist":false,"reworded":false,"where":{"page":1,"line":14}},{"kind":"dont","text":"無断欠勤を続けるなど、就業規則の解雇の事由に当たることをしない。","from":{"quote":"無断欠勤を続けるなど、就業規則の解雇の事由に当たることをすると、解雇されることがある。","line":16,"line_end":16,"found":true},"reasons":[{"text":"解雇されることがある。","from":{"quote":"解雇されることがある。","line":16,"line_end":16,"found":true},"stated":true,"where":{"page":1,"line":16}}],"checklist":false,"reworded":false,"where":{"page":1,"line":16}},{"kind":"do","text":"異常に気づいたら、すぐに親方に知らせる。","from":{"quote":"異常に気づいたら、すぐに親方に知らせる。","line":18,"line_end":18,"found":true},"reasons":[{"text":"早く知らせれば、事故を防げるため。","from":{"quote":"早く知らせれば、事故を防げるためである。","line":18,"line_end":18,"found":true},"stated":true,"where":{"page":1,"line":18}}],"checklist":false,"reworded":false,"where":{"page":1,"line":18}},{"kind":"dont","text":"異常に気づいてから 10 分たって知らせるような遅い知らせ方をしない。","from":{"quote":"異常に気づいてから 10 分たって知らせるのでは遅い。","line":19,"line_end":19,"found":true},"reasons":[{"text":"早く知らせれば、事故を防げるため。","from":{"quote":"早く知らせれば、事故を防げるためである。","line":18,"line_end":18,"found":true},"stated":true,"where":{"page":1,"line":18}}],"checklist":false,"reworded":false,"where":{"page":1,"line":19}}]', '2026-11-02 16:52:01');
